function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Rebuild the tree from the level-order list, then check the search-tree order with value bounds.
  const nodes = [{ val: root[0], left: null, right: null }];
  let parent = 0;
  let side = 'left';
  for (let i = 1; i < root.length; i++) {
    if (parent >= nodes.length) return 'The list has more entries than the tree has child slots.';
    if (root[i] !== null) {
      const node = { val: root[i], left: null, right: null };
      nodes[parent][side] = node;
      nodes.push(node);
    }
    if (side === 'left') side = 'right'; else { side = 'left'; parent++; }
  }
  if (nodes.length > 100) return 'The tree has at most 100 nodes.';
  for (const node of nodes) if (!Number.isInteger(node.val) || node.val < 0 || node.val > 1000) return 'Node values are integers between 0 and 1000.';
  const stack = [[nodes[0], -Infinity, Infinity]];
  while (stack.length) {
    const [node, low, high] = stack.pop();
    if (node.val <= low || node.val >= high) return 'root must be a binary search tree with distinct values.';
    if (node.left) stack.push([node.left, low, node.val]);
    if (node.right) stack.push([node.right, node.val, high]);
  }
  return null;
}

