  // Gather every value with a breadth-first walk, sort them, and build a fresh right-going chain.
  const values = [];
  const queue = [root];
  while (queue.length) {
    const node = queue.shift();
    if (!node) continue;
    values.push(node.val);
    queue.push(node.left, node.right);
  }
  values.sort((a, b) => a - b);
  let head = null;
  for (let i = values.length - 1; i >= 0; i--) head = new TreeNode(values[i], null, head);
  return head;
}

