function generate(rand, size) {
  const large = size === 'large';
  const count = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 8);
  const span = large ? 1000 : (rand() < 0.5 ? 20 : 1000);
  // Pick distinct values, then insert them into a BST in a random (sometimes sorted) order.
  const picked = new Set();
  while (picked.size < count) picked.add(Math.floor(rand() * (span + 1)));
  const values = [...picked];
  const shape = rand();
  if (shape < 0.15) values.sort((a, b) => a - b);
  else if (shape < 0.3) values.sort((a, b) => b - a);
  else for (let i = values.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [values[i], values[j]] = [values[j], values[i]]; }
  let rootNode = null;
  for (const val of values) {
    const node = { val, left: null, right: null };
    if (!rootNode) { rootNode = node; continue; }
    let at = rootNode;
    for (;;) {
      const side = val < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [rootNode];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (node === null) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
